<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/tag_engine.php';$db=tt_db_open(true);$q=trim((string)($_GET['q']??''));$rows=[];if($q!==''){$parsed=tt_parse_tag_token($q);$name=$parsed?$parsed['canon']:$q;$s=tt_prepare($db,'SELECT ti.`post_id`,ti.`tag`,ti.`raw_token`,ti.`is_numeric`,ti.`polarity`,ti.`comparator`,ti.`numeric_value`,p.`title`,p.`name`,p.`dt` FROM `tag_index` ti JOIN `posts` p ON p.`id`=ti.`post_id` WHERE ti.`tag`=? ORDER BY p.`dt` DESC LIMIT 100');$s->bind_param('s',$name);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}else{$r=$db->query('SELECT ti.`post_id`,ti.`tag`,ti.`raw_token`,ti.`is_numeric`,ti.`polarity`,ti.`comparator`,ti.`numeric_value`,p.`title`,p.`name`,p.`dt` FROM `tag_index` ti JOIN `posts` p ON p.`id`=ti.`post_id` ORDER BY p.`dt` DESC,ti.`id` DESC LIMIT 100');if($r){$rows=$r->fetch_all(MYSQLI_ASSOC);$r->free();}}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Tags</title></head><body><?php if(!empty($_SESSION['loggedin'])): tt_nav('tags.php'); else: ?><nav class="navtop"><div><h1><a href="/">TABLETIME</a></h1><a href="post.php">Posts</a><a href="login.php">Login</a></div></nav><?php endif;?><main class="content"><h2>Numeric + topic tag index</h2><form><input name="q" value="<?=tt_h($q)?>" placeholder="food=0.5, late=-15000-7500, table, -angry"><button>Inspect tag</button></form><p class="meta">Numeric and measureless/topic tags are indexed separately for one-to-one relevance scoring. +/− polarity is preserved.</p><section class="grid"><?php foreach($rows as $r):?><article class="card"><h3><a href="post.php#post-<?=(int)$r['post_id']?>"><?=tt_h($r['title'])?></a></h3><p><b><?=tt_h($r['raw_token'])?></b></p><p class="meta">canonical <?=tt_h($r['tag'])?> · <?=$r['is_numeric']?'numeric':'topic'?> · polarity <?=((int)$r['polarity']<0?'-':'+')?><?php if($r['is_numeric']):?> · <?=tt_h($r['comparator']?:'=')?> <?=tt_h($r['numeric_value'])?><?php endif;?></p></article><?php endforeach;?></section></main></body></html>
